<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;

/**
 * `review_links` table of the MyAT database.
 * Generated by `php artisan app:generate-models`; add relationships below.
 *
 * @property int|null $ID
 * @property string|null $TransferType
 * @property string|null $From
 * @property string|null $To
 * @property string|null $ReviewLink
 */
class ReviewLink extends Model
{
    protected $table = 'review_links';

    protected $primaryKey = 'ID';

    public $incrementing = true;

    protected $keyType = 'int';

    public $timestamps = false;

    protected $guarded = [];

    protected function casts(): array
    {
        return [
            'ID' => 'integer',
        ];
    }

    protected static function booted(): void
    {
        // All columns are NOT NULL; PHPRunner saved blanks as ''.
        static::saving(function (ReviewLink $link): void {
            foreach (['TransferType', 'From', 'To', 'ReviewLink'] as $column) {
                $link->{$column} ??= '';
            }
        });
    }
}
